import json, re, random, chess, sys, time
rules = [(re.compile(p), r) for p, r in json.load(open("re.json"))]
def run(fen):
    for p, r in rules: fen = p.sub(r, fen)
    return fen.split("\n")
def expected(board):
    s=set()
    for m in board.legal_moves:
        if m.promotion and m.promotion!=chess.QUEEN: continue
        b=board.copy(); b.push(m); s.add(" ".join(b.fen().split(" ")[:-2]))
    return s
def check(fen):
    out=[" ".join(x.split(" ")[:-2]) for x in run(fen)]
    exp=expected(chess.Board(fen))
    ok = len(out)==len(exp) and all(x in exp or x.rpartition(" ")[0]+" -" in exp for x in out)
    if not ok:
        print("FAIL", fen); print(sorted(set(out)-exp)); print(sorted(exp-set(out))); sys.exit(1)
print(run("<REDACTED_B64> w kq - 0 1"))
random.seed(int(sys.argv[1]) if len(sys.argv)>1 else 0)
n=0; t=time.time()
for g in range(300):
    b=chess.Board()
    while not b.is_game_over():
        if b.turn==chess.WHITE:
            check(b.fen()); n+=1
        b.push(random.choice(list(b.legal_moves)))
print("ok", n, time.time()-t)
EOF
